import itertools
import random

def has_short_cycle(edges, n=30, girth=7):
    # Build adj list
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    # BFS from each node to find shortest cycle
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = [start]
        i = 0
        while i < len(q):
            u = q[i]; i+=1
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < girth:
                        return True
    return False

def is_3_colorable(edges, n=30):
    # Simple backtracking to check 3-coloring
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    colors = [-1] * n
    def bt(node):
        if node == n:
            return True
        used = [False]*3
        for nei in adj[node]:
            if colors[nei] != -1:
                used[colors[nei]] = True
        for c in range(3):
            if not used[c]:
                colors[node] = c
                if bt(node+1):
                    return True
                colors[node] = -1
        return False
    # Try starting with different colors for 0 if needed, but since symmetric
    return bt(0)

